def nl_anti_join(outer, inner, match):
    for o in outer:
        found = False
        for i in inner:
            if match(o, i):
                found = True
                break  # 일치 발견 즉시 중단
        if not found:
            yield o  # 일치 행이 없는 외부 행만 반환

def hash_anti_join(outer, inner, key):
    built = {key(i) for i in inner}  # 내부로 해시 빌드
    for o in outer:
        if key(o) not in built:
            yield o

